  Array.prototype.forEach.call(root.querySelectorAll("[data-action]"), function (btn) {
    btn.onclick = function (ev) {
      ev.stopPropagation();
      var idx = Number(btn.getAttribute("data-idx"));
      var item = combined[idx];
      if (!item) return;
      var action = btn.getAttribute("data-action");
      if (action === "locate") onLocate(item, btn);
      else if (action === "fix") onFix(item, btn);
      else if (action === "dismiss") {
        onDismiss(item, btn);
        // Visually remove the card.
        var card = root.querySelector("#_eli3_lr_card_" + idx);
        if (card && card.parentNode) card.parentNode.removeChild(card);
      }
    };
  });

  // Header close + footer Home — both go home.
  root.querySelector("._eli3_lr_results_close").onclick = onHome;
  root.querySelector("._eli3_lr_results_home").onclick = onHome;

  return {
    refresh: function () {
      // Caller re-runs renderResults for a fresh paint. Cheaper than
      // diffing — the page is shallow.
    },
  };
}

jsonTools.init:
function init(eli) {
  if (!eli.events) eli.events = { guard: function (fn) { return fn; }, safeAsync: function (p) { return p; } };
  var bundle = eli.tools._loaded["legal_risks"];
  if (!bundle) return;
  var efns = bundle._eliEngineFns || {};
  var vfns = bundle._eliViewFns || {};
  var analyze       = efns.analyze;
  var renderResults = vfns.renderResults;
  if (!analyze || !renderResults) {
    eli.log.event("tool", "legal_risks_load_failed", {
      hasAnalyze: !!analyze, hasView: !!renderResults,
    });
    return;
  }

  // ─── Doc-hash helper (matches build_draft + ask_eli shape) ────────
  function _hashContent(text) {
    if (!text) return "empty";
    var s = String(text), hash = 0;
    for (var i = 0; i < s.length; i++) {
      hash = ((hash << 5) - hash) + s.charCodeAt(i);
      hash |= 0;
    }
    return "h" + (hash >>> 0).toString(36);
  }

  // ─── Load risk rules from IDB ─────────────────────────────────────
  // STORE_RISK_RULES = "risk_rules" — populated by risk_rules_manager
  // tool + the __data_risk_rules data bundle.
  function _loadRules() {
    if (!eli.storage || typeof eli.storage.getAll !== "function") return Promise.resolve([]);
    return eli.storage.getAll("risk_rules").then(function (rows) {
      return (rows || []).filter(function (r) {
        return r && r.id && String(r.id).charAt(0) !== "_";
      });
    }).catch(function () { return []; });
  }

  // ─── Read doc text (with stable per-paragraph anchors) ────────────
  // FROM v2 getLegalTextWithAnchors. v3 host exposes
  // readTextWithAnchors which inserts bookmarks named `_ELI_LR_<i>`
  // and returns [{id, text}, ...]. We flatten back to a single text
  // string for the AI prompt; the bookmarks stay in the doc for the
  // LOCATE button to scroll to clauses later.
  function _readDocText() {
    if (!eli.host || typeof eli.host.readTextWithAnchors !== "function") {
      // Fallback — plain text read.
      if (eli.host && typeof eli.host.readText === "function") {
        return eli.host.readText().then(function (t) { return { text: t || "", anchors: [] }; });
      }
      return Promise.resolve({ text: "", anchors: [] });
    }
    return eli.host.readTextWithAnchors({ prefix: "_ELI_LR_", minLen: 5 }).then(function (anchors) {
      anchors = anchors || [];
      var text = anchors.map(function (a) { return a.text; }).join("\n");
      return { text: text, anchors: anchors };
    }).catch(function () {
      return { text: "", anchors: [] };
    });
  }

  // ─── Locate a clause in the document ──────────────────────────────
  // LOCATE button handler. Scrolls Word's selection to the clause and
  // briefly highlights. Tries anchor lookup first (cheaper), falls
  // back to body.search.
  function _locateClause(item) {
    var query = String(item.text || item.clause_ref || "").trim();
    if (!query) {
      if (typeof showToast === "function") showToast("No clause text to locate.", "warn");
      return Promise.resolve(false);
    }
    if (eli.host && typeof eli.host.findRange === "function") {
      return eli.host.findRange(query.substring(0, 250)).then(function (r) {
        if (r && r.anchor && typeof eli.host.highlightAnchor === "function") {
          return eli.host.highlightAnchor(r.anchor).then(function () { return true; });
        }
        if (!r) {
          if (typeof showToast === "function") showToast("Clause not found in document.", "warn");
          return false;
        }
        return true;
      }).catch(function () {
        if (typeof showToast === "function") showToast("Locate failed.", "err");
        return false;
      });
    }
    // Fallback — raw search.
    if (eli.host && typeof eli.host.runRaw === "function") {
      return eli.host.runRaw("legal_risks:locate", function (context) {
        var res = context.document.body.search(query.substring(0, 250), {
          matchCase: false, matchWholeWord: false, ignorePunct: true, ignoreSpace: true,
        });
        res.load("items");
        return context.sync().then(function () {
          if (!res.items || !res.items.length) return false;
          res.items[0].select();
          res.items[0].scrollIntoView();
          return context.sync().then(function () { return true; });
        });
      }).catch(function () { return false; });
    }
    return Promise.resolve(false);
  }

  // ─── FIX button — open a rewrite dialog ───────────────────────────
  // v2 used showRewriteEditor — a modal with the original text + the
  // AI's suggested rewrite + apply-as-redline. v3 surgical-apply lives
  // under eli.host.applySurgicalRedline (Phase planned). Until that
  // lands, dispatch to ask_eli's action card path if available, or
  // show a basic preview dialog.
  function _fixClause(item) {
    var original = String(item.text || "").trim();
    var suggestion = String(item.fix_suggestion || "").trim();
    if (!original) {
      if (typeof showToast === "function") showToast("No original text to fix.", "warn");
      return;
    }
    // Prefer ask_eli's action-card flow (already has surgical redline).
    var askEliCompose = eli.get && eli.get("ask_eli", "compose");
    if (typeof askEliCompose === "function" && suggestion) {
      try {
        askEliCompose({
          question: "Rewrite this clause: " + suggestion,
          context: [
            { role: "user", content: "I want to rewrite this clause:\n\n" + original },
            { role: "model", content: "Suggested rewrite: " + suggestion },
          ],
        });
        return;
      } catch (e) { /* fall through */ }
    }
    // Fallback — show a simple preview dialog.
    if (typeof showEliDialog === "function") {
      showEliDialog({
        variant: "info",
        tier: "premium",
        icon: "⚡",
        title: "Proposed Rewrite",
        body:
          '<div style="font-size:11px; color:#64748b; text-transform:uppercase; letter-spacing:0.4px; margin-bottom:6px;">Original</div>' +
          '<div style="background:#f8fafc; padding:10px; border-left:3px solid #c62828; font: 500 12px/1.5 Georgia, serif; color:#475569; margin-bottom:14px;">' +
            String(original).replace(/&/g, "&amp;").replace(/</g, "&lt;") +
          '</div>' +
          '<div style="font-size:11px; color:#1565c0; text-transform:uppercase; letter-spacing:0.4px; margin-bottom:6px;">Suggested</div>' +
          '<div style="background:#fff8e1; padding:10px; border-left:3px solid #1565c0; font: 500 12px/1.5 Georgia, serif; color:#0f172a;">' +
            String(suggestion || "(no suggestion)").replace(/&/g, "&amp;").replace(/</g, "&lt;") +
          '</div>',
        secondary: { label: "Close" },
      });
    }
  }

  // ─── DISMISS — track in session feed ──────────────────────────────
  function _dismissItem(item) {
    if (eli.activity && eli.activity.add) {
      try {
        eli.activity.add({
          type: "legal-360-dismiss",
          icon: "✕",
          label: "Risk Dismissed",
          summary: String(item.title || "Risk").substring(0, 80),
          payload: { title: item.title, clauseRef: item.clause_ref },
        });
      } catch (e) {}
    }
  }

  // ─── Open the scan UI ─────────────────────────────────────────────
  function _open(preloadOpts) {
    preloadOpts = preloadOpts || {};
    if (!eli.ai || typeof eli.ai.hasApiKey !== "function" || !eli.ai.hasApiKey()) {
      if (typeof showToast === "function") showToast("Set a Gemini API key in Settings → Global first.", "warn");
      if (eli.settings && typeof eli.settings.show === "function") eli.settings.show();
      return;
    }
    var mount = document.getElementById("_eli3_dashboard_root");
    if (!mount) {
      eli.log.event("tool", "legal_risks_open_no_mount", {});
      if (typeof showToast === "function") showToast("Dashboard root missing — try reopening ELI", "err");
      return;
    }
    try { if (eli.stats && eli.stats.record) eli.stats.record("appOpenedRisk"); } catch (e) {}
    try {
      var cur = eli.fsm.getCurrent ? eli.fsm.getCurrent() : null;
      if (cur === "idle") eli.fsm.transition("scanning");
    } catch (e) {}

    // Show a loading overlay while the AI runs.
    if (typeof setLoading === "function") {
      try { setLoading(true, "legal"); } catch (e) {}
    }

    var launcherCfg = (typeof window !== "undefined" && window._legalRisksLauncherSettings) || {};
    var showUsage = launcherCfg.showUsage !== false;
    var docType = (typeof window !== "undefined" && window._eliDocType) || preloadOpts.docType || "";

    Promise.all([
      _readDocText(),
      _loadRules(),
    ]).then(function (r) {
      var doc = r[0];
      var rules = r[1];
      eli.log.event("tool", "legal_risks_input_ready", {
        textLen: (doc.text || "").length,
        anchors: (doc.anchors || []).length,
        rulesAvailable: rules.length,
      });
      return analyze({
        text: doc.text,
        rules: rules,
        docType: docType,
        showUsage: showUsage,
        docHash: _hashContent(doc.text),
      }, { ai: eli.ai, host: eli.host });
    }).then(function (result) {
      try { if (eli.stats && eli.stats.record) eli.stats.record("docsReviewed"); } catch (e) {}
      if (result.items && result.items.length) {
        try { eli.stats.record("risksFound", result.items.length); } catch (e) {}
      }
      if (typeof setLoading === "function") {
        try { setLoading(false); } catch (e) {}
      }
      try { eli.fsm.transition("rendering"); } catch (e) {}

      renderResults({
        mount: mount,
        data: result,
        rulesActive: result.rulesActive,
        showUsage: showUsage,
        onHome: function () {
          try { eli.fsm.transition("idle"); } catch (e) {}
          if (eli.dashboard && typeof eli.dashboard.goHome === "function") eli.dashboard.goHome();
        },
        onLocate: function (item) { _locateClause(item); },
        onFix: function (item) { _fixClause(item); },
        onDismiss: function (item) { _dismissItem(item); },
      });

      // Activity feed — restorable entry so clicking re-renders this view.
      var summary;
      if (!result.items || !result.items.length) {
        summary = "✅ No risks detected";
      } else {
        var parts = [];
        if (result.riskCount) parts.push(result.riskCount + " Risk" + (result.riskCount !== 1 ? "s" : ""));
        if (result.usageCount) parts.push(result.usageCount + " Ops");
        summary = parts.join(" · ") + " detected";
      }
      if (eli.activity && eli.activity.add) {
        try {
          eli.activity.add({
            type: "legal-360",
            icon: "⚡",
            label: "Legal Risks",
            summary: summary,
            payload: result,
            provenance: result.provenance,
            restoreChannel: "activity_restore",
            restoreKey: "legal-360",
          });
        } catch (e) {}
      }
    }).catch(function (err) {
      if (typeof setLoading === "function") {
        try { setLoading(false); } catch (e) {}
      }
      eli.log.event("tool", "legal_risks_open_failed", { msg: err && err.message });
      if (err && err.message && /abort|cancel/i.test(err.message)) {
        if (typeof showCancelledState === "function") showCancelledState();
        return;
      }
      if (typeof showToast === "function") {
        showToast("Analysis failed: " + (err && err.message || "unknown"), "err");
      }
    });
  }

  // ─── Activity-feed restore — re-renders a past Legal Risks result ─
  function _restoreActivity(payload) {
    if (!payload) return;
    var mount = document.getElementById("_eli3_dashboard_root");
    if (!mount) {
      if (typeof showToast === "function") showToast("Dashboard root missing", "err");
      return;
    }
    try { eli.fsm.transition("rendering"); } catch (e) {}
    // payload may be the result object OR the wrapper with .items.
    var data = (payload && payload.items) ? payload : (payload.raw || { items: [] });
    var rulesActive = !!(payload.rulesActive || (payload.raw && payload.raw._rulesWereActive));
    renderResults({
      mount: mount,
      data: data,
      rulesActive: rulesActive,
      showUsage: true,
      onHome: function () {
        try { eli.fsm.transition("idle"); } catch (e) {}
        if (eli.dashboard && typeof eli.dashboard.goHome === "function") eli.dashboard.goHome();
      },
      onLocate: function (item) { _locateClause(item); },
      onFix: function (item) { _fixClause(item); },
      onDismiss: function (item) { _dismissItem(item); },
    });
  }

  // ─── Channels ─────────────────────────────────────────────────────
  eli.register({
    tile: { app_legal_risks: function () { _open(); } },
    // Programmatic launch from legal_review's Launch Analysis.
    legal_risks: { run: _open },
    // Activity-feed restore.
    activity_restore: { "legal-360": _restoreActivity },
  });

  // Back-compat shim for v2 callers that expect window.runDeal360Analysis.
  window.runDeal360Analysis = function () { _open(); };

  eli.log.event("tool", "legal_risks_initialized", {});
}

