._eli3_lr_results_btn_dismiss:hover {
  border-color: #fca5a5;
  color: #b91c1c;
  background: #fef2f2;
}

/* ── Footer Home button ───────────────────────────────────────────── */
._eli3_lr_results_home {
  margin: 14px;
  padding: 10px 16px;
  font: 800 11px/1 'Inter', sans-serif;
  letter-spacing: 0.5px;
  text-transform: uppercase;
  background: linear-gradient(180deg, #fff 0%, #f1f5f9 100%);
  border: 1px solid #cbd5e1;
  color: #475569;
  cursor: pointer;
  transition: all 0.15s;
  align-self: flex-start;
}
._eli3_lr_results_home:hover {
  border-color: #1565c0;
  color: #1565c0;
}
